@@ -1,5 +1,3 @@
-import { identity } from '../../function/identity.ts';
-import { meanBy as meanByToolkit } from '../../math/meanBy.ts';
 import { ValueIteratee } from '../_internal/ValueIteratee.ts';
 import { iteratee as iterateeToolkit } from '../util/iteratee.ts';

@@ -30,5 +28,22 @@ export function meanBy<T>(items: ArrayLike<T> | null | undefined, iteratee?: Val
     return NaN;
   }

-  return meanByToolkit(Array.from(items), iterateeToolkit(iteratee ?? identity));
+  const length = items.length;
+
+  if (length === 0) {
+    return NaN;
+  }
+
+  const getValue = iteratee == null ? undefined : iterateeToolkit(iteratee);
+  let sum: any = undefined;
+
+  for (let i = 0; i < length; i++) {
+    const current = getValue ? getValue(items[i]) : items[i];
+
+    if (current !== undefined) {
+      sum = sum === undefined ? current : sum + current;
+    }
+  }
+
+  return sum / length;
 }

